"""TC-05: rolling volatility from earlier returns (RISK-02), against the golden fixture."""

import pytest

from risk import Returns
from risk.vol import rolling_vol


def test_tc05_rolling_vol_matches_expected(golden) -> None:
    given, expected = golden("risk", "TC-05")
    data = given["returns"]
    returns = Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={ticker: tuple(values) for ticker, values in data["values"].items()},
    )

    vol = rolling_vol(returns, given["window"])

    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=expected["tol"], rel=0)
"""Shared test setup (human-owned): Hypothesis profiles, and golden cases and contract artifacts by name."""

from __future__ import annotations

import importlib.util
import json
import os
from pathlib import Path

import pytest
from hypothesis import settings

settings.register_profile("dev", max_examples=20)
settings.register_profile("ci", max_examples=500)
settings.load_profile(os.getenv("HYPOTHESIS_PROFILE", "dev"))

TESTS = Path(__file__).resolve().parent


@pytest.fixture
def golden():
    """golden("risk", "TC-05") -> (input, expected), read from tests/fixtures/<pkg>/<TC>/."""

    def load(pkg: str, tc: str) -> tuple[dict, dict]:
        folder = TESTS / "fixtures" / pkg / tc
        return (
            json.loads((folder / "input.json").read_text()),
            json.loads((folder / "expected.json").read_text()),
        )

    return load


@pytest.fixture
def contract_sample():
    """contract_sample("risk.Returns") -> the sample payload in tests/contracts/<name>/sample.json."""

    def load(name: str) -> dict:
        return json.loads((TESTS / "contracts" / name / "sample.json").read_text())

    return load


@pytest.fixture
def contract_fake():
    """contract_fake("mdata.load_prices") -> the fake module in tests/contracts/<name>/fake.py."""

    def load(name: str):
        path = TESTS / "contracts" / name / "fake.py"
        spec = importlib.util.spec_from_file_location(f"fake_{name.replace('.', '_')}", path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    return load
